    reg [31:0] spl_plane;    // (aux0+oc)*plane_sz
    reg [31:0] oy_row;       // oy      * in_w

    // -----------------------------------------------------------------------
    // SOFTMAX state
    //
    // Softmax normalises across CHANNELS at one spatial position:
    //     y[c] = exp(x[c] - max) / sum_c exp(x[c] - max)
    //
    // That needs two passes over the channel axis before a single output byte
    // can be written, so it cannot use the one-element-in/one-element-out loop
    // the other ops share. This walks positions in the outer loop and channels
    // twice in the inner one.
    //
    // Until now LAYER_OP_SOFTMAX fell through `default` and copied its input.
    // Both C2PSA attention blocks therefore had no attention at all -- the
    // scores went straight through unnormalised, which is a plausible-looking
    // wrong answer rather than a failure.
