    reg [15:0] sm_ch;         // channel within the position
    reg signed [7:0] sm_max;  // running max over the channel axis
    reg [23:0] sm_sum;        // sum of exp terms, Q0.8 accumulated
    reg [7:0]  sm_exp;        // exp term for the channel in flight

    // Serial divider for the softmax normalisation. See E_SM_DIV.
