    // so the index is 16*(max - x), saturating at the bottom of the table.
    wire [15:0] sm_delta16 = ({8'h0, sm_max} - {8'h0, operand_a}) << 4;
    wire [7:0]  sm_idx = (sm_delta16 > 16'd255) ? 8'd255 : sm_delta16[7:0];

    // ---- per-op source address for the current output element --------------
    // UPSAMPLE: nearest neighbour, source pixel is (oy/f, ox/f). The factor is
    // 2 for every upsample in yolo26n, so this is a shift, not a divide.
    wire [15:0] up_f  = g_aux0[15:0];
    reg  [4:0]  up_sh;                    // log2(up_f), latched at job start
    wire [15:0] up_y  = oy >> up_sh;
    wire [15:0] up_x  = ox >> up_sh;
    wire [31:0] up_off = oc_plane + up_y*g_in_w + up_x;

