        E_RD_A   = 5'd1,
        E_RD_AW  = 5'd2,
        E_RD_B   = 5'd3,
        E_RD_BW  = 5'd4,
        E_COMPUTE= 5'd5,
        E_WR     = 5'd6,
        E_WR_W   = 5'd7,
        E_NEXT   = 5'd8,
        E_DONE   = 5'd9,
        E_ERR    = 5'd10,
        E_WR_GO  = 5'd11,   // wr_data settled, assert wr_start
