            LAYER_OP_UPSAMPLE: begin a_base = g_src0; a_off = up_off;  end
            LAYER_OP_CONCAT:   begin a_base = cat_base; a_off = cat_off; end
            LAYER_OP_SPLIT:    begin a_base = g_src0; a_off = spl_off; end
            LAYER_OP_MAXPOOL:  begin a_base = g_src0; a_off = pool_off; end
