            rd_start <= 1'b0; rd_addr <= 64'h0; rd_len <= 8'd0;
            wr_start <= 1'b0; wr_addr <= 64'h0; wr_len <= 8'd0; wr_data <= 64'h0; wr_strb <= 8'h00;
            idx      <= 32'd0; total <= 32'd0; pk <= 4'd0; sub <= 4'd0;
            sm_pos <= 16'd0; sm_ch <= 16'd0; sm_max <= 8'sd0;
            sm_sum <= 24'd0; sm_exp <= 8'd0; sm_phase <= 2'd0;
            sd_num <= 24'd0; sd_den <= 24'd0; sd_q <= 24'd0;
            sd_rem <= 24'd0; sd_i <= 5'd0; sd_busy <= 1'b0;
            acc8     <= 16'sh0;
            oc       <= 16'd0; oy <= 16'd0; ox <= 16'd0;
            pk_y     <= 4'd0;  pk_x <= 4'd0;
