                    g_src0  <= src0; g_src1 <= src1; g_dst <= dst;
                    g_in_w  <= in_w; g_in_h <= in_h; g_in_c <= in_c;
                    g_in_c1 <= in_c1;
                    g_out_w <= out_w; g_out_h <= out_h; g_out_c <= out_c;
                    g_aux0  <= aux0; g_aux1 <= aux1;
                    total   <= out_w * out_h * out_c;
                    sm_pos   <= 16'd0; sm_ch <= 16'd0;
                    sm_sum   <= 24'd0; sm_phase <= 2'd0;
                    sm_max   <= 8'sd0;
