                rd_addr  <= {32'h0, g_src1 + add_off};
                rd_len   <= 8'd1;
                rd_start <= 1'b1;
                state    <= E_RD_BW;
            end

            E_RD_BW: begin
                if (rd_data_valid)
                    operand_b <= rd_data[{add_off[2:0], 3'b000} +: 8];
