                LAYER_OP_MAXPOOL: begin
                    if ($signed(operand_a) > acc8) acc8 <= $signed(operand_a);
                    if (pk == pool_k*pool_k - 1) begin
                        pk      <= 4'd0;
                        pk_y    <= 4'd0;
                        pk_x    <= 4'd0;
                        wr_data <= {56'h0,
                                    ($signed(operand_a) > acc8)
