                        pk    <= pk + 4'd1;
                        // pk_y/pk_x track pk/pool_k and pk%pool_k without a
                        // divider: pk advances by one, so they are an odometer.
                        if (pk_x == pool_k[3:0] - 4'd1) begin
                            pk_x <= 4'd0;
                            pk_y <= pk_y + 4'd1;
                        end else begin
                            pk_x <= pk_x + 4'd1;
                        end
                        state <= E_RD_A;
                    end
                end

                default: begin
                    // Concat / Split / Upsample are pure copies.
                    wr_data <= {56'h0, operand_a};
                    state   <= E_WR;
                end
                endcase
            end

            // ------------------------------------------------------------
            // Every op above leaves its INT8 result in lane 0 of wr_data.
            // Shift it into the lane the destination address selects and
            // enable only that lane: with an all-ones strobe a single-byte
            // store also writes its 7 neighbours, and since idx advances by
            // one each iteration those neighbours are the bytes written next.
            // Every op above leaves its INT8 result in lane 0 of wr_data. Shift
            // it into the lane the destination address selects and enable only
            // that lane: with an all-ones strobe a single-byte store also
            // writes its 7 neighbours, and since idx advances by one each
            // iteration those neighbours are the bytes written next.
            //
            // The shift happens HERE, one state before wr_start, so wr_data is
            // already in its final position on the cycle the master samples it.
            // Doing both in the same state asserts wr_start alongside a
            // non-blocking update that has not landed yet.
            E_WR: begin
                wr_addr <= {32'h0, e_dst_addr};
                wr_data <= {56'h0, wr_data[7:0]} << {e_dst_addr[2:0], 3'b000};
                wr_strb <= 8'h01 << e_dst_addr[2:0];
                wr_len  <= 8'd1;
                state   <= E_WR_GO;
            end

            E_WR_GO: begin
                wr_start <= 1'b1;
                state    <= E_WR_W;
            end

            E_WR_W: begin
                if (wr_done) begin
                    if (wr_error) begin error <= 1'b1; state <= E_ERR; end
                    else if (g_op == LAYER_OP_SOFTMAX) begin
                        // Next channel at this position, then the next
                        // position with a fresh max/sum.
                        if (sm_ch == g_in_c - 16'd1) begin
                            sm_ch    <= 16'd0;
                            sm_phase <= 2'd0;
                            sm_sum   <= 24'd0;
                            if (sm_pos == g_in_w * g_in_h - 16'd1)
                                state <= E_DONE;
                            else begin
                                sm_pos <= sm_pos + 16'd1;
                                state  <= E_SM_RD;
                            end
                        end else begin
                            sm_ch <= sm_ch + 16'd1;
                            state <= E_SM_RD;
                        end
                    end
                    else state <= E_NEXT;
                end
            end

            // ---- softmax ---------------------------------------------------
            E_SM_RD: begin
                rd_addr  <= {32'h0, g_src0 + sm_src_off};
                rd_len   <= 8'd1;
                rd_start <= 1'b1;
                state    <= E_SM_RDW;
            end

            E_SM_RDW: begin
                if (rd_data_valid)
                    operand_a <= rd_data[{sm_src_off[2:0], 3'b000} +: 8];
                if (rd_done) begin
                    if (rd_error) begin error <= 1'b1; state <= E_ERR; end
                    else state <= E_SM_STEP;
                end
            end

            E_SM_STEP: begin
                case (sm_phase)
                // Pass 0: largest score in this position's channel vector.
                2'd0: begin
                    if (sm_ch == 16'd0 ||
                        $signed(operand_a) > $signed(sm_max))
                        sm_max <= $signed(operand_a);
                    if (sm_ch == g_in_c - 16'd1) begin
                        sm_ch    <= 16'd0;
                        sm_sum   <= 24'd0;
                        sm_phase <= 2'd1;
                        state    <= E_SM_RD;
                    end else begin
                        sm_ch <= sm_ch + 16'd1;
                        state <= E_SM_RD;
                    end
                end

                // Pass 1: total of exp(x - max) over the same vector.
                2'd1: begin
                    sm_sum <= sm_sum + {16'h0, exp_rom[sm_idx]};
                    if (sm_ch == g_in_c - 16'd1) begin
                        sm_ch    <= 16'd0;
                        sm_phase <= 2'd2;
                        state    <= E_SM_RD;
                    end else begin
                        sm_ch <= sm_ch + 16'd1;
                        state <= E_SM_RD;
                    end
                end

                // Pass 2: emit exp(x - max) / sum, as an INT8 code.
                //
                // The result is a probability in [0,1]; the exporter gives the
                // consumer a scale of 127 codes per unit, so the code is
                // 127 * exp/sum. Computed as (exp * 127) / sum with the
                // division done by the same restoring loop used elsewhere --
                // sum is not a constant, so there is nothing to hoist.
                2'd2: begin
                    sm_exp  <= exp_rom[sm_idx];
                    wr_data <= 64'h0;
                    state   <= E_SM_WRW;
                end

                default: sm_phase <= 2'd0;
                endcase
            end

            // Divide, then store one byte. The divide is short: numerator is
            // at most 127*255 and the quotient fits in 8 bits.
            // Start the serial divide. `num / sm_sum` was written here as a
            // single-cycle variable divide, and it was the design's critical
            // path by a wide margin: the whole -53.5 ns of setup failure at
            // 50 MHz, on every one of the six worst paths.
            //
            // The comment that used to sit here said the divide was "short"
            // because the quotient fits in 8 bits. That is the wrong measure --
            // divider hardware is sized by the OPERANDS, and both are 24 bits.
            // This is the same defect the plan's A1 rewrite removed from the
            // conv engine's reduction seed.
            E_SM_WRW: begin
                sd_num   <= {8'h0, sm_exp} * 24'd127;
                sd_den   <= sm_sum;
                sd_q     <= 24'd0;
                sd_rem   <= 24'd0;
                sd_i     <= 5'd23;
                // A zero sum means every exp term was zero; the quotient is
                // then defined as zero rather than dividing by it.
                sd_busy  <= (sm_sum != 24'd0);
                state    <= E_SM_DIV;
            end

            // One restoring-division step per cycle: 24 cycles for a 24-bit
            // numerator. Softmax runs once per channel over a handful of
            // channels, so the cost is invisible next to the memory traffic
            // the layer already does.
            E_SM_DIV: begin
                if (!sd_busy) begin
                    wr_data <= {56'h0, (sd_q > 24'd127) ? 8'd127 : sd_q[7:0]}
                               << {sm_dst_off[2:0], 3'b000};
                    wr_strb <= 8'h01 << sm_dst_off[2:0];
                    wr_addr <= {32'h0, g_dst + sm_dst_off};
                    wr_len  <= 8'd1;
                    state   <= E_WR_GO;
                end else begin
                    sd_rem_n = {sd_rem[22:0], sd_num[sd_i]};
                    if (sd_rem_n >= sd_den) begin
                        sd_rem     <= sd_rem_n - sd_den;
                        sd_q[sd_i] <= 1'b1;
                    end else begin
                        sd_rem <= sd_rem_n;
                    end
                    if (sd_i == 5'd0) sd_busy <= 1'b0;
                    else              sd_i    <= sd_i - 5'd1;
                end
            end

            E_NEXT: begin
                acc8 <= -16'sd128;
                if (idx == total - 1) state <= E_DONE;
                else begin
                    idx   <= idx + 32'd1;
                    state <= E_RD_A;

                    // Advance (oc,oy,ox) and every product derived from it.
                    // Each carry costs one add, versus the divider chain this
                    // replaced. ox is the fast axis, matching the flat layout
                    // of `idx` that the write side uses (g_dst + idx).
                    if (ox == g_out_w - 16'd1) begin
                        ox <= 16'd0;
                        if (oy == g_out_h - 16'd1) begin
                            oy       <= 16'd0;
                            oy_row   <= 32'd0;
                            oc       <= oc + 16'd1;
                            oc_plane <= oc_plane + plane_sz;
                            // CONCAT: channels below in_c index src0 directly;
                            // at/above it they index src1 from zero again, so
                            // the plane offset restarts at that boundary.
                            cat_plane <= ((oc + 16'd1) == g_in_c)
                                       ? 32'd0
                                       : cat_plane + plane_sz;
                            spl_plane <= spl_plane + plane_sz;
                        end else begin
                            oy     <= oy + 16'd1;
                            oy_row <= oy_row + {16'h0, g_in_w};
                        end
                    end else begin
                        ox <= ox + 16'd1;
                    end
                end
            end

            // ------------------------------------------------------------
            E_DONE: begin
                busy <= 1'b0; done <= 1'b1; state <= E_IDLE;
            end

            E_ERR: begin
                busy <= 1'b0; done <= 1'b1; error <= 1'b1; state <= E_IDLE;
            end

            default: state <= E_IDLE;
            endcase

            if (state != E_IDLE && done) done <= 1'b0;
        end
    end

endmodule
